package com.petlis.service.impl;
import com.petlis.common.exception.BusinessException;import java.util.*;import java.time.format.DateTimeFormatter;import java.io.*;import org.apache.poi.xssf.usermodel.XSSFWorkbook;
/** PHP export column content, without spreadsheet auto-coercion of identifiers or formulas. */
final class LegacyOrderExportWorkbook {
 static final List<String> HEADERS=List.of("样本唯一编号","报告唯一编号","编号","动物名称","物种","芯片号","年龄","病理诊断结果","生日","采样部位","主人名称","采样日期","收到样本日期","发送样本日期","寄出报告日期","性别","德国编号","医院名称","采样方式","地区","城市","检测项","检测项代码","价格","付款状态","付款代码","作废状态(0=不作废)","医生姓名");
 private static final List<String> KEYS=List.of("ListDiagnosisProjectId","DiagnosisDetailId","UserNO","AnimalName","ExportSpecies","ChipNO","Age","DiagnosticResults","Birthday","SampleArea","MasterName","CollectDt","ReceiveSampleDt","SendSampleDt","SendReportDt","ExportSex","ReportNO","ExportHospital","ExportSample","CityId","ExportCity","TestName","TestNO","ExportPrice","ExportPayLabel","PayStatus2","IsCheckPass","DoctorName");
 static String cityName(long id,Map<Long,Map<String,Object>> cities){var names=new ArrayList<String>();var seen=new HashSet<Long>();while(id!=0){if(!seen.add(id))throw new BusinessException(409,"城市层级存在循环，请先核对资料");var row=cities.get(id);if(row==null){names.add("-");break;}names.add(Objects.toString(row.get("CityName"),""));Object parent=row.get("BelongCity_cityId");id=parent instanceof Number n?n.longValue():0;}if(names.isEmpty())return "-";Collections.reverse(names);return String.join("/",names);}
 private static String text(Object value){if(value==null)return "";if(value instanceof java.time.LocalDateTime t)return t.format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));if(value instanceof java.sql.Timestamp t)return t.toLocalDateTime().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));return value.toString();}
 static byte[] write(List<Map<String,Object>> rows,Map<Long,Map<String,Object>> cities,long total,Integer status){try(var workbook=new XSSFWorkbook();var output=new ByteArrayOutputStream()){
  var sheet=workbook.createSheet("送检明细");var header=sheet.createRow(0);for(int i=0;i<HEADERS.size();i++){header.createCell(i).setCellValue(HEADERS.get(i));sheet.setColumnWidth(i,22*256);}sheet.createFreezePane(0,1);int number=1;
  for(var source:rows){var data=new HashMap<>(source);Object city=source.get("CityId");data.put("ExportCity",cityName(city instanceof Number n?n.longValue():0,cities));data.put("ExportPrice",LegacyPricingRules.display(Objects.toString(source.get("TestPrice"),"0")));int exempt=source.get("IsCheckPass") instanceof Number n?n.intValue():0;data.put("ExportPayLabel",source.get("PayStatus2")==null&&exempt!=1?"":LegacyFinanceService.payLabel(exempt,source.get("PayStatus2") instanceof Number n?n.intValue():0));var row=sheet.createRow(number++);for(int i=0;i<KEYS.size();i++)row.createCell(i).setCellValue(text(data.get(KEYS.get(i))));}
  var info=workbook.createSheet("导出说明");String[][] details={{"范围","与当前送检列表一致：授权数据组、非负状态及当前状态筛选"},{"符合条件明细总数",String.valueOf(total)},{"本文件明细数",String.valueOf(rows.size())},{"单次上限","10000（按原PHP明细编号倒序）"},{"是否达到部分导出",total>rows.size()?"是，请按条件分批导出":"否"},{"状态筛选",status==null?"全部非负状态":String.valueOf(status)},{"单元格","按文本保留编号、芯片号、金额与原日期，文本不作为公式执行"}};for(int i=0;i<details.length;i++){var row=info.createRow(i);row.createCell(0).setCellValue(details[i][0]);row.createCell(1).setCellValue(details[i][1]);}info.setColumnWidth(0,26*256);info.setColumnWidth(1,100*256);workbook.write(output);return output.toByteArray();
 }catch(IOException e){throw new BusinessException(500,"送检明细导出失败，请重试");}}
}
